-- Split phrases marked as split_pending
-- Generated from word_frequencies entries

-- Split د دې -> د + دې (preposition)

INSERT OR IGNORE INTO word_frequencies (pashto_word, frequency_total, pos)
SELECT 'د', 0, 'preposition'
WHERE NOT EXISTS (SELECT 1 FROM word_frequencies WHERE pashto_word = 'د');


INSERT OR IGNORE INTO word_frequencies (pashto_word, frequency_total, pos)
SELECT 'دې', 0, NULL
WHERE NOT EXISTS (SELECT 1 FROM word_frequencies WHERE pashto_word = 'دې');


UPDATE word_frequencies 
SET pos = 'split', pashto_word = pashto_word || ' [SPLIT]'
WHERE id = 11469;


