SELECT 'پټو', 0, NULL
WHERE NOT EXISTS (SELECT 1 FROM word_frequencies WHERE pashto_word = 'پټو');


INSERT OR IGNORE INTO word_frequencies (pashto_word, frequency_total, pos)
SELECT 'ته', 0, 'postposition'
WHERE NOT EXISTS (SELECT 1 FROM word_frequencies WHERE pashto_word = 'ته');


